package com.tencent.weknora.knowledge;

import static org.junit.jupiter.api.Assertions.*;
import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.databind.node.*;import com.sun.net.httpserver.HttpServer;import com.tencent.weknora.task.*;
import java.net.*;import java.time.*;import java.util.*;import java.util.concurrent.CancellationException;import java.util.concurrent.atomic.AtomicInteger;
import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.beans.factory.config.AutowireCapableBeanFactory;

/** Production beans, shared multipart/Doc/Post/Summary refresh and live profile provider HTTP; Hikari1. */
@org.springframework.boot.test.context.SpringBootTest(properties={"weknora.jwt-secret=isolated-native-pipeline-trace-secret","weknora.bridge.enabled=false","weknora.knowledge.processing.enabled=true","weknora.knowledge.upload.enabled=true","weknora.tasks.enabled=true","weknora.tasks.poll-millis=3600000","weknora.retrieve-driver=sqlite","SSRF_WHITELIST=127.0.0.1","SSRF_DNS_WHITELIST_ONLY=true","NEO4J_ENABLE=false","logging.level.root=WARN","debug=false"})
@org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc
class KnowledgeBaseProfilePipelineHttpIntegrationTest {
 @org.springframework.test.context.DynamicPropertySource static void properties(org.springframework.test.context.DynamicPropertyRegistry p){KnowledgeProcessingSpanPipelineHttpIntegrationTest.properties(p);}
 @Autowired AutowireCapableBeanFactory beans;@Autowired KnowledgeBaseProfileHandler profile;@Autowired SummaryGenerationHandler summary;@Autowired KnowledgeRepository knowledge;
 final KnowledgeProcessingSpanPipelineHttpIntegrationTest f=new KnowledgeProcessingSpanPipelineHttpIntegrationTest();final ObjectMapper json=new ObjectMapper();final AtomicInteger calls=new AtomicInteger();HttpServer server;Runnable during=()->{};
 @BeforeEach void setup()throws Exception{beans.autowireBean(f);f.setup();f.jdbc.update("DELETE FROM java_task_attempts WHERE task_id IN (SELECT id FROM java_task_jobs WHERE tenant_id=8 AND type='kb:profile' AND json_extract(payload,'$.knowledge_base_id')='trace-kb')");f.jdbc.update("DELETE FROM java_task_jobs WHERE tenant_id=8 AND type='kb:profile' AND json_extract(payload,'$.knowledge_base_id')='trace-kb'");f.jdbc.update("UPDATE knowledge_bases SET profile_config=?,generated_profile=NULL,auto_tag_config='{}',question_generation_config='{}' WHERE id='trace-kb'","{\"enabled\":true}".getBytes(java.nio.charset.StandardCharsets.UTF_8));server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/v1/",exchange->{try{var body=json.readTree(exchange.getRequestBody());ObjectNode response;if(exchange.getRequestURI().getPath().endsWith("chat/completions")){if(body.path("max_tokens").asInt()==800){calls.incrementAndGet();assertEquals(.2,body.path("temperature").asDouble());assertTrue(body.path("messages").get(1).path("content").asText().contains("<aggregate>"));during.run();}String reply=body.path("max_tokens").asInt()==800?"{\"gist\":\"Release collection\",\"topics\":[\"migration\"],\"typical_questions\":[\"How are releases approved?\"]}":"{\"summary\":\"Release summary\",\"gist\":\"Release document\",\"topics\":[\"migration\"]}";response=json.createObjectNode().set("choices",json.createArrayNode().add(json.createObjectNode().put("finish_reason","stop").set("message",json.createObjectNode().put("role","assistant").put("content",reply))));}else{var data=json.createArrayNode();for(int i=0;i<body.path("input").size();i++)data.add(json.createObjectNode().put("index",i).set("embedding",json.createArrayNode().add(1).add(0).add(0)));response=json.createObjectNode().set("data",data);}byte[] bytes=json.writeValueAsBytes(response);exchange.getResponseHeaders().set("Content-Type","application/json");exchange.sendResponseHeaders(200,bytes.length);try(var out=exchange.getResponseBody()){out.write(bytes);}}finally{exchange.close();}});server.start();var parameters=json.createObjectNode().put("provider","generic").put("base_url","http://127.0.0.1:"+server.getAddress().getPort()+"/v1");parameters.set("embedding_parameters",json.createObjectNode().put("dimension",3));f.jdbc.update("UPDATE models SET parameters=? WHERE id='trace-embedding'",parameters.toString());f.jdbc.update("INSERT INTO models(id,tenant_id,name,type,source,parameters,is_builtin,status) VALUES('trace-profile-model',8,'unknown','KnowledgeQA','remote',?,false,'active') ON CONFLICT(id) DO UPDATE SET parameters=excluded.parameters",parameters.toString());f.jdbc.update("UPDATE knowledge_bases SET summary_model_id='trace-profile-model' WHERE id='trace-kb'");}
 @AfterEach void cleanup(){if(server!=null)server.stop(0);f.jdbc.update("UPDATE knowledge_bases SET tenant_id=8,profile_config='{}',generated_profile=NULL,summary_model_id='' WHERE id='trace-kb'");}
 String prepared(boolean enrich)throws Exception{String id=f.upload("Release approvals and access checkpoints for the migration. "+UUID.randomUUID());if(enrich)f.jdbc.update("UPDATE knowledges SET metadata=? WHERE id=?",json.createObjectNode().set("process_overrides",json.createObjectNode().put("summary_enabled",true)).toString(),id);var doc=f.claim("default");f.document.execute(doc,f.cancellation(doc));f.tasks.complete(doc,json.createObjectNode());var post=f.claim("postprocess");f.postprocess.execute(post,f.cancellation(post));f.tasks.complete(post,json.createObjectNode());return id;}
 TaskRecord profileJob(){var ids=f.jdbc.queryForList("SELECT id FROM java_task_jobs WHERE type='kb:profile' AND tenant_id=8 AND status='pending'",String.class);assertEquals(1,ids.size());f.jdbc.update("UPDATE java_task_jobs SET available_at=0 WHERE id=?",ids.getFirst());return f.claim("summary");}
 JsonNode stored()throws Exception{var raw=f.jdbc.queryForObject("SELECT generated_profile FROM knowledge_bases WHERE id='trace-kb'",Object.class);return raw==null?json.nullNode():raw instanceof byte[] b?json.readTree(b):json.readTree(raw.toString());}
 @Test void completedSharedUploadSchedulesDebouncedProfileWithoutOwningDocumentCounter()throws Exception{String id=prepared(false);var rows=f.jdbc.queryForList("SELECT id FROM java_task_jobs WHERE tenant_id=8 AND type='kb:profile' AND status='pending'",String.class).stream().map(taskId->f.tasks.get(8,taskId).orElseThrow()).toList();assertEquals(1,rows.size());var queued=rows.getFirst();assertEquals("summary",queued.queue());assertEquals(3,queued.maxAttempts());assertEquals(300000,queued.timeoutMillis());assertEquals(30000,queued.availableAt()-queued.createdAt());assertEquals(0,f.jdbc.queryForObject("SELECT pending_subtasks_count FROM knowledges WHERE id=?",Integer.class,id));var job=profileJob();assertEquals("ready",profile.execute(job,f.cancellation(job)).path("status").asText());f.tasks.complete(job,json.createObjectNode());assertEquals("Release collection",stored().path("gist").asText());assertEquals(1,calls.get());assertEquals("done",f.get(id,"spans",f.callerToken,200).path("trace").path("status").asText());assertEquals("caller",f.jdbc.queryForObject("SELECT actor_user_id FROM audit_logs WHERE action='knowledge.created' AND target_id=? ORDER BY created_at DESC LIMIT 1",String.class,id));}
 @Test void summaryCompletionRefreshUsesSameWindowAndSeesItsDocumentProfile()throws Exception{String id=prepared(true);var summaryIds=f.jdbc.queryForList("SELECT id FROM java_task_jobs WHERE type='summary:generation' AND status='pending'",String.class);assertEquals(1,summaryIds.size());f.jdbc.update("UPDATE java_task_jobs SET available_at=0 WHERE id=?",summaryIds.getFirst());var job=f.claim("summary");summary.execute(job,f.cancellation(job));f.tasks.complete(job,json.createObjectNode());assertEquals(0,f.jdbc.queryForObject("SELECT pending_subtasks_count FROM knowledges WHERE id=?",Integer.class,id));var p=profileJob();profile.execute(p,f.cancellation(p));f.tasks.complete(p,json.createObjectNode());assertTrue(stored().path("stats").path("profiled_count").asInt()>0);assertEquals(1,calls.get());}
 @Test void cachedDuplicateAvoidsSecondProviderCallAndForcedJobCallsAgain()throws Exception{prepared(false);var job=profileJob();profile.execute(job,f.cancellation(job));assertEquals("aggregate_unchanged",profile.execute(job,f.cancellation(job)).path("skipped").asText());assertEquals(1,calls.get());f.tasks.complete(job,json.createObjectNode());assertTrue(profile.enqueue(8,knowledge.knowledgeBase(8,"trace-kb"),true,json.createObjectNode().put("language","en-US")));var forced=profileJob();assertTrue(forced.payload().path("force").asBoolean());profile.execute(forced,f.cancellation(forced));f.tasks.complete(forced,json.createObjectNode());assertEquals(2,calls.get());}
 @Test void leaseLostDuringChatNeverPublishesProfileOrChangesExistingDocumentIndexes()throws Exception{String id=prepared(false);long indexes=f.count("lite_embeddings",id);var job=profileJob();during=()->f.jdbc.update("UPDATE java_task_jobs SET lease_owner='successor' WHERE id=?",job.id());assertThrows(CancellationException.class,()->profile.execute(job,f.cancellation(job)));assertTrue(stored().isNull());assertEquals(indexes,f.count("lite_embeddings",id));}
 @Test void changedOwnerDuringChatNeverWritesIntoTheNewTenant()throws Exception{prepared(false);var job=profileJob();during=()->f.jdbc.update("UPDATE knowledge_bases SET tenant_id=9 WHERE id='trace-kb'");assertThrows(TaskFailure.class,()->profile.execute(job,f.cancellation(job)));assertTrue(stored().isNull());}
 @Test void explicitTaskCancelDuringChatKeepsPreviousDescription()throws Exception{prepared(false);var job=profileJob();during=()->assertTrue(f.tasks.cancel(8,job.id()));assertThrows(CancellationException.class,()->profile.execute(job,f.cancellation(job)));assertTrue(stored().isNull());}
 JsonNode publicGenerate(String token,int expected)throws Exception{var response=f.mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post("/api/v1/knowledge-bases/trace-kb/profile/generate").header("Authorization","Bearer "+token).header("Accept-Language","en-US")).andReturn().getResponse();assertEquals(expected,response.getStatus(),response.getContentAsString());return json.readTree(response.getContentAsByteArray());}
 @Test void synchronousSharedGenerationForcesCacheRefreshWithoutQueueingAnotherTask()throws Exception{prepared(false);var job=profileJob();profile.execute(job,f.cancellation(job));f.tasks.complete(job,json.createObjectNode());int tasks=f.jdbc.queryForObject("SELECT COUNT(*) FROM java_task_jobs",Integer.class);var output=publicGenerate(f.callerToken,200);assertEquals("Release collection",output.path("data").path("gist").asText());assertEquals("ready",output.path("data").path("status").asText());assertEquals(2,calls.get());assertEquals(tasks,f.jdbc.queryForObject("SELECT COUNT(*) FROM java_task_jobs",Integer.class));publicGenerate(f.foreignToken,403);assertEquals(2,calls.get());}
 @Test void synchronousDisabledConfigStillSupportsForcedGenerationAndMissingModelReports400()throws Exception{prepared(false);f.jdbc.update("UPDATE knowledge_bases SET profile_config='{}' WHERE id='trace-kb'");publicGenerate(f.callerToken,200);assertEquals(1,calls.get());f.jdbc.update("UPDATE knowledge_bases SET summary_model_id='' WHERE id='trace-kb'");var error=publicGenerate(f.callerToken,400);assertEquals(1000,error.path("error").path("code").asInt());assertEquals("failed",stored().path("status").asText());assertEquals("Release collection",stored().path("gist").asText());}
 @Test void settingsEnableSchedulesRefreshAfterCommitAndNeverCountsAsDocumentEnhancement()throws Exception{f.jdbc.update("UPDATE knowledge_bases SET profile_config='{}' WHERE id='trace-kb'");var response=f.mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.put("/api/v1/knowledge-bases/trace-kb").header("Authorization","Bearer "+f.callerToken).contentType("application/json").content("{\"name\":\"Trace KB\",\"config\":{\"profile_config\":{\"enabled\":true}}}")).andReturn().getResponse();assertEquals(200,response.getStatus(),response.getContentAsString());var job=profileJob();assertEquals(8,job.tenantId());assertEquals("summary",job.queue());}

 @Test void actualAuthenticationRequiresManageCapabilityAndKbScopeAndKeepsSharedViewerCap()throws Exception{
  prepared(false);String key="profile-key-"+UUID.randomUUID();String hash=com.tencent.weknora.security.AuthFilter.hashApiKey(key);
  f.jdbc.update("INSERT INTO tenant_api_keys(tenant_id,name,key_hash,api_key,full_access,capabilities,knowledge_base_ids) VALUES(8,'Profile operator',?,?,false,'[\"retrieve\"]','[\"trace-kb\"]')",hash,key);
  try{
   assertEquals(403,keyGenerate(key));assertEquals(0,calls.get());
   f.jdbc.update("UPDATE tenant_api_keys SET capabilities='[\"manage_kbs\"]',knowledge_base_ids='[\"other\"]' WHERE key_hash=?",hash);assertEquals(403,keyGenerate(key));assertEquals(0,calls.get());
   f.jdbc.update("UPDATE tenant_api_keys SET knowledge_base_ids='[\"trace-kb\"]' WHERE key_hash=?",hash);assertEquals(200,keyGenerate(key));assertEquals(1,calls.get());
   f.jdbc.update("UPDATE tenant_api_keys SET tenant_id=7 WHERE key_hash=?",hash);assertEquals(403,keyGenerate(key));assertEquals(1,calls.get());
   f.jdbc.update("UPDATE tenant_api_keys SET full_access=true WHERE key_hash=?",hash);assertEquals(200,keyGenerate(key));assertEquals(2,calls.get());
  }finally{f.jdbc.update("DELETE FROM tenant_api_keys WHERE key_hash=?",hash);}
 }
 int keyGenerate(String key)throws Exception{return f.mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post("/api/v1/knowledge-bases/trace-kb/profile/generate").header("X-API-Key",key)).andReturn().getResponse().getStatus();}

}
